import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"免费云端","description":"MiniTavern 免费云端 API：各厂商免费/试用额度与永久免费模型，BYOK 填写连接；无付费 Key 时的起步方案。","frontmatter":{"title":"免费云端","description":"MiniTavern 免费云端 API：各厂商免费/试用额度与永久免费模型，BYOK 填写连接；无付费 Key 时的起步方案。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"免费云端 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 免费云端 API：各厂商免费/试用额度与永久免费模型，BYOK 填写连接；无付费 Key 时的起步方案。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/free-cloud"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/free-cloud"}]]},"headers":[],"relativePath":"free-cloud/index.md","filePath":"free-cloud/index.md","lastUpdated":1787217957000}'),o={name:"free-cloud/index.md"};function n(i,t,l,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="免费云端" tabindex="-1">免费云端 <a class="header-anchor" href="#免费云端" aria-label="Permalink to &quot;免费云端&quot;">​</a></h1><p>MiniTavern 是 <strong>BYOK（自备密钥）</strong>：不送云端额度，需你自己注册厂商或推理平台的 API Key。<br> 本文汇总<strong>常见免费 / 试用额度</strong>与填入 App 的方法；额度与政策会变动，<strong>以各官网控制台实时显示为准</strong>。</p><blockquote><p>安全提醒：API Key 等同密码。只填进 App 本机安全存储，不要发到群聊、截图公开或提交到公开仓库。</p></blockquote><h2 id="先选一条最快路径" tabindex="-1">先选一条最快路径 <a class="header-anchor" href="#先选一条最快路径" aria-label="Permalink to &quot;先选一条最快路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>建议</th><th>App 平台</th></tr></thead><tbody><tr><td>中国大陆、想尽快开聊</td><td><a href="#智谱-ai-glm">智谱 Flash 免费模型</a> 或 <a href="#硅基流动-siliconflow">硅基流动免费模型</a></td><td>自定义 (OpenAI)</td></tr><tr><td>一个 Key 试文本 + 生图（多模态）</td><td><a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a></td><td>自定义 (OpenAI) / Images</td></tr><tr><td>一把 Key 试 GPT / Gemini 等 <code>*-free</code> + 生图</td><td><a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a></td><td>自定义 (OpenAI) / Images</td></tr><tr><td>编码向精选网关、有限时 Free 文本</td><td><a href="/ultra_guides/free-cloud/opencode-zen">OpenCode Zen</a></td><td>自定义 (OpenAI)</td></tr><tr><td>想要官方中文大模型试用</td><td><a href="#通义千问--阿里云百炼">通义千问 · 阿里云百炼</a></td><td>Qwen</td></tr><tr><td>想要推理 / 代码向</td><td><a href="#deepseek">DeepSeek</a></td><td>DeepSeek</td></tr><tr><td>海外账号、多模态文本</td><td><a href="#google-gemini">Google Gemini</a></td><td>Gemini(Google)</td></tr><tr><td>一个 Key 试很多免费开源模型</td><td><a href="/ultra_guides/free-cloud/openrouter">OpenRouter <code>:free</code></a></td><td>OpenRouter</td></tr><tr><td>不知道还有哪些免费厂</td><td><a href="/ultra_guides/free-cloud/freellm">FreeLLM 目录</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>）</td><td>见目录</td></tr><tr><td>极速开源推理</td><td><a href="#groq">Groq</a></td><td>自定义 (OpenAI)</td></tr><tr><td>不想用云端</td><td><a href="/ultra_guides/local/">部署本地模型</a></td><td>自定义 (OpenAI)</td></tr></tbody></table><p>填 Key 的通用步骤见 <a href="/ultra_guides/manual/model-link">模型连接</a>。本机部署见 <a href="/ultra_guides/local/">部署本地模型</a> · <a href="/ultra_guides/quickstart">30 分钟通关</a>。</p><h2 id="在-minitavern-里怎么填" tabindex="-1">在 MiniTavern 里怎么填 <a class="header-anchor" href="#在-minitavern-里怎么填" aria-label="Permalink to &quot;在 MiniTavern 里怎么填&quot;">​</a></h2><p>路径：<strong>设置 → 模型 → 模型连接 → 新建</strong></p><ol><li>选对 <strong>模型平台</strong>（下表「App 平台」列）。</li><li>粘贴 <strong>API Key</strong>；自定义平台再填 <strong>Base URL</strong>。</li><li>选择或手填 <strong>模型 ID</strong>（必须与厂商文档一致，大小写敏感）。</li><li>点 <strong>测试</strong> → 成功后再设为 <strong>默认</strong>。</li></ol><table tabindex="0"><thead><tr><th>厂商</th><th>App 平台</th><th>Base URL（常见）</th><th>说明</th></tr></thead><tbody><tr><td>Gemini</td><td>Gemini(Google)</td><td>预设即可</td><td>协议为 Gemini，勿当 OpenAI 填</td></tr><tr><td>OpenRouter</td><td>OpenRouter</td><td>预设即可</td><td>免费模型 ID 常带 <code>:free</code></td></tr><tr><td>通义 / 百炼</td><td>Qwen</td><td>预设（可切国际站）</td><td>Key 用<strong>通用</strong> API Key，勿用 Coding Plan 专属 Key</td></tr><tr><td>DeepSeek</td><td>DeepSeek</td><td>预设即可</td><td></td></tr><tr><td>智谱 / 硅基 / Agnes / AIHubMix / Zen / Groq / Mistral 等</td><td><strong>自定义 (OpenAI)</strong></td><td>见各节</td><td>OpenAI 兼容网关</td></tr></tbody></table><hr><h2 id="国内常用-大陆直连优先" tabindex="-1">国内常用（大陆直连优先） <a class="header-anchor" href="#国内常用-大陆直连优先" aria-label="Permalink to &quot;国内常用（大陆直连优先）&quot;">​</a></h2><h3 id="智谱-ai-glm" tabindex="-1">智谱 AI (GLM) <a class="header-anchor" href="#智谱-ai-glm" aria-label="Permalink to &quot;智谱 AI (GLM)&quot;">​</a></h3><p>适合：想<strong>长期免费</strong>跑通对话（Flash 系列），中文角色扮演友好。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>官网 / Key</td><td><a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">open.bigmodel.cn</a> → 控制台 → API Keys</td></tr><tr><td>免费方式</td><td><code>GLM-*-Flash</code> 等永久免费模型；新用户常另有体验额度（以控制台为准）</td></tr><tr><td>绑卡</td><td>通常不需要</td></tr><tr><td>Base URL</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>模型示例</td><td><code>glm-4.5-flash</code>、<code>glm-4.7-flash</code>（名称以模型广场为准）</td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong></td></tr></tbody></table><p>步骤：注册 → 创建 API Key → 在 App 选自定义 OpenAI → 填 Base URL 与 Key → 模型填 Flash 系列 ID → 测连。</p><h3 id="硅基流动-siliconflow" tabindex="-1">硅基流动 (SiliconFlow) <a class="header-anchor" href="#硅基流动-siliconflow" aria-label="Permalink to &quot;硅基流动 (SiliconFlow)&quot;">​</a></h3><p>适合：一个 Key 试用多种开源聊天模型；部分图像模型也有免费档。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>官网 / Key</td><td><a href="https://cloud.siliconflow.cn" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a> → 账户 → API 密钥</td></tr><tr><td>免费方式</td><td><strong>免费模型</strong>调用不计费（名称不含 <code>Pro/</code> 前缀）；需完成实名后可用全部免费模型</td></tr><tr><td>限速</td><td>按模型固定 RPM/TPM；见<a href="https://docs.siliconflow.cn/cn/userguide/rate-limits/rate-limit-and-upgradation" target="_blank" rel="noreferrer">官方 Rate Limits</a></td></tr><tr><td>Base URL</td><td><code>https://api.siliconflow.cn/v1</code></td></tr><tr><td>模型示例</td><td>在模型广场选「免费」标签，如 <code>Qwen/Qwen3-8B</code> 等（列表会变）</td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong></td></tr></tbody></table><p>注意：同名模型可能有免费版与 <code>Pro/...</code> 收费版，填错会扣费。账单里免费模型消耗应为 0。</p><h3 id="通义千问-·-阿里云百炼" tabindex="-1">通义千问 · 阿里云百炼 <a class="header-anchor" href="#通义千问-·-阿里云百炼" aria-label="Permalink to &quot;通义千问 · 阿里云百炼&quot;">​</a></h3><p>适合：想用官方 Qwen 系列；MiniTavern 有 <strong>Qwen</strong> 预设。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>开通</td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">阿里云百炼控制台</a>（华北 2 / 北京）同意协议后自动开通</td></tr><tr><td>免费方式</td><td><strong>新人免费额度</strong>：多数模型约 <strong>100 万 Token / 模型</strong>，约 <strong>90 天</strong>有效；模型间额度不互通</td></tr><tr><td>Key</td><td>百炼 → API-Key；请用<strong>通用 Key</strong>（Token Plan / Coding Plan 专属 Key <strong>不消耗</strong>免费额度）</td></tr><tr><td>App</td><td><strong>Qwen</strong>（国内站预设；国际站可切换）</td></tr><tr><td>防扣费</td><td>控制台开启「<strong>免费额度用完即停</strong>」，避免额度耗尽后按量扣款</td></tr></tbody></table><p>官方说明：<a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新人免费额度</a>。额度耗尽或过期后继续调用会产生费用。</p><p>生图（万相 / Qwen-Image 等）若参与新人额度，可在 <strong>设置 → 生图 → 生图连接</strong> 选 Qwen 平台；是否免费以控制台该模型额度条为准。</p><h3 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h3><p>适合：推理、长文、高性价比；额度用完后很便宜，但<strong>不是永久 0 元</strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>官网 / Key</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys</td></tr><tr><td>免费方式</td><td>新用户通常有<strong>注册赠金 / 体验额度</strong>（金额与规则以控制台为准，会调整）</td></tr><tr><td>App</td><td><strong>DeepSeek</strong></td></tr><tr><td>模型示例</td><td><code>deepseek-v4-flash</code>、<code>deepseek-v4-pro</code>（以<a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">官方文档</a>为准）</td></tr></tbody></table><p>赠金用尽后按量计费；账户无余额时请求会失败。</p><h3 id="魔搭-modelscope-api-inference" tabindex="-1">魔搭 ModelScope API-Inference <a class="header-anchor" href="#魔搭-modelscope-api-inference" aria-label="Permalink to &quot;魔搭 ModelScope API-Inference&quot;">​</a></h3><p>适合：已有阿里云实名，想试用社区开源模型推理。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>Token</td><td><a href="https://modelscope.cn" target="_blank" rel="noreferrer">modelscope.cn</a> → 访问令牌</td></tr><tr><td>免费方式</td><td>注册用户 API-Inference 有日请求配额（总量与单模型上限以<a href="https://modelscope.cn/docs/model-service/API-Inference/limits" target="_blank" rel="noreferrer">官方限额</a>为准）</td></tr><tr><td>Base URL</td><td><code>https://api-inference.modelscope.cn/v1</code></td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong></td></tr></tbody></table><hr><h2 id="国际-聚合平台" tabindex="-1">国际 / 聚合平台 <a class="header-anchor" href="#国际-聚合平台" aria-label="Permalink to &quot;国际 / 聚合平台&quot;">​</a></h2><h3 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h3><p>适合：一个免费 Key 同时试<strong>文本对话与生图</strong>（同属 Flash 免费档）；视频能力见官网，App 暂无内置视频入口。</p><p>完整介绍、模型分表与填 Key 步骤见专页：<strong><a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a></strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>官网 / Key</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a> · <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>免费方式</td><td>Free Access：Flash 文本 / 图像等可免费调用（有 RPM 限速）</td></tr><tr><td>Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr><tr><td>文本示例</td><td><code>agnes-2.5-flash</code></td></tr><tr><td>生图示例</td><td><code>agnes-image-2.1-flash</code>（生图连接选 <strong>自定义 (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong> / <strong>自定义 (OpenAI Images)</strong></td></tr></tbody></table><h3 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h3><p>适合：想用 OpenCode 精选网关上的 <strong>Free 文本模型</strong>（如 <code>mimo-v2.5-free</code>）；多数旗舰仍按量付费，注意自动充值。</p><p>完整说明见专页：<strong><a href="/ultra_guides/free-cloud/opencode-zen">OpenCode Zen</a></strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>官网 / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> · <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">文档</a></td></tr><tr><td>免费方式</td><td>定价表中标 Free 的模型（上限内）；其它按量付费</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/v1</code></td></tr><tr><td>文本示例</td><td><code>mimo-v2.5-free</code>、<code>hy3-free</code>、<code>big-pickle</code></td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong>（优先 chat/completions 兼容 ID）</td></tr></tbody></table><h3 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h3><p>适合：一把 Key 试用多款平台补贴的 <code>*-free</code> 模型（含 GPT / Gemini / GLM 等）及 <strong>GPT-Image-2-free</strong> 生图；通常无需绑卡。</p><p>完整说明见专页：<strong><a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a></strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>官网 / Key</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> · <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">免费模型文</a></td></tr><tr><td>免费方式</td><td>模型 ID 以 <code>-free</code> 结尾；按模型 RPM / 日额度</td></tr><tr><td>Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr><tr><td>文本示例</td><td><code>gpt-4o-free</code>、<code>gpt-5.5-free</code>、<code>coding-glm-5.1-free</code></td></tr><tr><td>生图示例</td><td><code>gpt-image-2-free</code>（<strong>自定义 (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong> / <strong>自定义 (OpenAI Images)</strong></td></tr></tbody></table><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><p>适合：多模态文本、长上下文；<strong>文本</strong>免费档较慷慨。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com/app/apikey</a></td></tr><tr><td>免费方式</td><td>部分 Gemini Flash / Lite <strong>文本</strong>模型有 Free tier（RPM / RPD 以 AI Studio 账户内显示为准）</td></tr><tr><td>绑卡</td><td>文本免费档通常不需要；<strong>生图类最新模型多数无 Free tier</strong></td></tr><tr><td>地区</td><td>欧盟 / 英国 / 瑞士等可能不可用免费档</td></tr><tr><td>隐私</td><td>免费档提示词可能用于改进产品（见 Google 条款）</td></tr><tr><td>App</td><td><strong>Gemini(Google)</strong></td></tr></tbody></table><p>聊天请选文本模型（如 <code>gemini-flash-latest</code>）。不要选名称带 <code>tts</code>、<code>image</code> 的专用 ID：测连会请求文字回复，TTS 只输出 AUDIO，会报 <code>response modalities (TEXT) is not supported</code>。语音/生图到对应功能里配置。</p><p>若测连/发送返回 <code>HTTP 404</code> 且含 <code>no longer available to new users</code>：该模型 ID 已下线或不再向新用户开放（如 <code>gemini-2.5-flash-lite</code>）。在模型连接中拉取最新列表，改选仍在线的 Flash / Lite（如 <code>gemini-flash-latest</code>）。不必改用 Interactions API。</p><p>若发送失败提示 <code>HTTP 429</code> 且含 <code>generate_content_free_tier_requests</code>（常见 limit: 20）：这是免费档每分钟请求次数用尽，按 <code>Please retry in …</code> 等待后再发即可。用量见 <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">ai.dev/rate-limit</a>；需要更高限额可在 AI Studio 开通结算。这与「账户没钱」或项目月度消费上限不同。</p><p>生图：Gemini <strong>App</strong> 网页端与 <strong>Developer API</strong> 额度不同；API 侧图像模型定价页常标注 Free tier 不可用。聊天用 Gemini、生图用本地 A1111/ComfyUI 是常见组合，见 <a href="/ultra_guides/local/image-gen/">生图模型部署</a>。</p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><p>适合：一个 Key 试用大量<strong>开源 / 第三方免费池</strong>；模型 ID 常以 <code>:free</code> 结尾。完整合集、分表与排错见专页：<strong><a href="/ultra_guides/free-cloud/openrouter">OpenRouter</a></strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>免费方式</td><td><code>:free</code> / 合集 Free；默认可约 20 RPM、日请求有限；充值可提高免费日限额（以官方为准）</td></tr><tr><td>App</td><td><strong>OpenRouter</strong></td></tr><tr><td>模型示例</td><td><code>openrouter/free</code>、<code>meta-llama/llama-3.3-70b-instruct:free</code>、<code>openai/gpt-oss-20b:free</code></td></tr><tr><td>合集</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> · 汇总 <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr></tbody></table><p>注意：免费上游可能记录提示词用于训练。若 <code>HTTP 429: Provider returned error</code>：换其它 <code>:free</code>、稍后重试，或 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a>。</p><h3 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h3><p>适合：要<strong>极低延迟</strong>的开源模型推理。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>免费方式</td><td>永久 Free tier（按模型 RPM / RPD / TPM，会调整）</td></tr><tr><td>绑卡</td><td>通常不需要</td></tr><tr><td>Base URL</td><td><code>https://api.groq.com/openai/v1</code></td></tr><tr><td>模型示例</td><td><code>llama-3.1-8b-instant</code>、<code>llama-3.3-70b-versatile</code>、<code>openai/gpt-oss-20b</code></td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong></td></tr></tbody></table><h3 id="mistral-ai" tabindex="-1">Mistral AI <a class="header-anchor" href="#mistral-ai" aria-label="Permalink to &quot;Mistral AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai/api-keys</a></td></tr><tr><td>免费方式</td><td>Experiment / 试用计划（月 token 量级以控制台为准）；提示词可能用于改进</td></tr><tr><td>Base URL</td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong></td></tr></tbody></table><h3 id="cerebras-sambanova-等高速推理" tabindex="-1">Cerebras / SambaNova 等高速推理 <a class="header-anchor" href="#cerebras-sambanova-等高速推理" aria-label="Permalink to &quot;Cerebras / SambaNova 等高速推理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>Key 入口</th><th>Base URL</th><th>备注</th></tr></thead><tbody><tr><td>Cerebras</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td><td><code>https://api.cerebras.ai/v1</code></td><td>免费档常有日 token 上限；可能要求支付方式</td></tr><tr><td>SambaNova</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td><td><code>https://api.sambanova.ai/v1</code></td><td>永久免费档 + 偶发赠金；限速较严</td></tr></tbody></table><p>App 均选 <strong>自定义 (OpenAI)</strong>，模型名以各控制台为准。</p><h3 id="github-models" tabindex="-1">GitHub Models <a class="header-anchor" href="#github-models" aria-label="Permalink to &quot;GitHub Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>入口</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>鉴权</td><td>GitHub Personal Access Token</td></tr><tr><td>Base URL</td><td><code>https://models.github.ai/inference</code></td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong></td></tr><tr><td>限制</td><td>按模型分级 RPM / RPD，适合轻量试用</td></tr></tbody></table><h3 id="nvidia-nim" tabindex="-1">NVIDIA NIM <a class="header-anchor" href="#nvidia-nim" aria-label="Permalink to &quot;NVIDIA NIM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>入口</td><td><a href="https://build.nvidia.com/explore/discover" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>Base URL</td><td><code>https://integrate.api.nvidia.com/v1</code></td></tr><tr><td>App</td><td><strong>自定义 (OpenAI)</strong>（若日后 App 恢复 Nvidia 预设亦可选用）</td></tr></tbody></table><hr><h2 id="试用额度-非永久免费" tabindex="-1">试用额度（非永久免费） <a class="header-anchor" href="#试用额度-非永久免费" aria-label="Permalink to &quot;试用额度（非永久免费）&quot;">​</a></h2><p>下列多为<strong>限时赠金</strong>，适合评测，不适合当唯一长期后端：</p><table tabindex="0"><thead><tr><th>厂商</th><th>常见情况</th><th>App</th></tr></thead><tbody><tr><td>OpenAI</td><td>控制台偶发试用金；主站 API <strong>无稳定永久免费档</strong></td><td>ChatGPT(OpenAI)</td></tr><tr><td>Anthropic Claude</td><td>控制台 starter credits，消耗快</td><td>Claude(Anthropic)</td></tr><tr><td>DeepSeek</td><td>见上文注册赠金</td><td>DeepSeek</td></tr><tr><td>阿里云百炼</td><td>新人 Token 额度（约 90 天）</td><td>Qwen</td></tr></tbody></table><p>用尽后请关闭自动扣款风险（删 Key、开「用完即停」、或改连免费模型 / 本地）。</p><hr><h2 id="免费生图怎么配" tabindex="-1">免费生图怎么配 <a class="header-anchor" href="#免费生图怎么配" aria-label="Permalink to &quot;免费生图怎么配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>费用</th><th>说明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/local/image-gen/">本机 A1111 / ComfyUI</a></td><td>电费 + 显卡</td><td>不限张数；手机连电脑局域网</td></tr><tr><td>硅基流动免费图像模型</td><td>免费模型 0 元</td><td>生图连接选 <strong>自定义 (OpenAI Images)</strong>，Base URL 同硅基 <code>…/v1</code>，模型选免费图像 ID</td></tr><tr><td><a href="/ultra_guides/free-cloud/agnes-ai">Agnes AI</a> 图像 Flash</td><td>Free Access</td><td>生图连接选 <strong>自定义 (OpenAI Images)</strong>，Base URL <code>https://apihub.agnes-ai.com/v1</code>，如 <code>agnes-image-2.1-flash</code></td></tr><tr><td><a href="/ultra_guides/free-cloud/aihubmix">AIHubMix</a></td><td><code>*-free</code> 图像模型</td><td>生图连接选 <strong>自定义 (OpenAI Images)</strong>，Base URL <code>https://aihubmix.com/v1</code>，如 <code>gpt-image-2-free</code></td></tr><tr><td>通义万相 / Qwen 生图</td><td>看百炼该模型是否有免费额度</td><td><strong>设置 → 生图 → 生图连接 → Qwen</strong></td></tr><tr><td>OpenAI / 多数 Gemini 图像 API</td><td>通常付费</td><td>无稳定 Free tier 时不要当「免费生图」</td></tr></tbody></table><p>聊天模型与生图连接可分开配置：例如聊天用智谱 Flash，生图用家里的 ComfyUI。</p><hr><h2 id="使用建议与排错" tabindex="-1">使用建议与排错 <a class="header-anchor" href="#使用建议与排错" aria-label="Permalink to &quot;使用建议与排错&quot;">​</a></h2><ol><li><strong>先测连再开聊</strong>：失败时点「查看详情」，对照 <a href="/ultra_guides/manual/errors">错误代码排错</a>。</li><li><strong>429 / 限流</strong>：换轻量模型、降记忆长度、错峰，或再备一个免费平台。</li><li><strong>突然扣费</strong>：检查是否用了 <code>Pro/</code> 收费模型、百炼未开「用完即停」、或赠金已耗尽。</li><li><strong>隐私</strong>：免费档常允许厂商用日志改进模型；敏感内容优先 <a href="/ultra_guides/local/">部署本地模型</a>。</li><li><strong>额度变更</strong>：本文数字为调研时常见值；以官网为准。更全的厂商/模型索引见 <a href="/ultra_guides/free-cloud/freellm">FreeLLM 目录</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> · <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>，非官方、每日更新）。</li></ol><h2 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h2><ul><li><a href="/ultra_guides/manual/model-link">模型连接</a> — App 内怎么填</li><li><a href="/ultra_guides/manual/getting-started">第一次使用</a></li><li><a href="/ultra_guides/free-cloud/freellm">FreeLLM 目录</a> — 更多免费厂商索引</li><li><a href="/ultra_guides/local/">部署本地模型</a> — 本机语言 / 生图服务</li><li><a href="/ultra_guides/local/image-gen/">生图模型部署</a> — A1111 / ComfyUI</li></ul>',83)])])}const b=e(o,[["render",n]]);export{g as __pageData,b as default};
